// n8n · workflow LANOPS-ENCAJE · nodo "Code: firma"  (sustituye a "Crypto: firma", 06-oct)
// Modo: Run Once for All Items · JavaScript
// Por qué: en n8n 2.x el nodo Crypto pide el secreto HMAC en una credencial y no admite
// {{ $env.ENCAJE_SECRET }}. Aquí el secreto se lee de la variable del servicio n8n en Railway
// (requiere N8N_BLOCK_ENV_ACCESS_IN_NODE=false) y nunca se copia a ningún sitio.
// Salida: el item del webhook + firma = HMAC-SHA256(ENCAJE_SECRET, 'encaje:' + u) en hex.
// SHA-256 en JavaScript puro: el Code de n8n no deja usar require('crypto') por defecto.

function sha256(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length, n = ((l + 9 + 63) >> 6) << 6, m = new Uint8Array(n);
  m.set(bytes); m[l] = 0x80;
  const bits = l * 8;
  m[n - 4] = (bits >>> 24) & 255; m[n - 3] = (bits >>> 16) & 255; m[n - 2] = (bits >>> 8) & 255; m[n - 1] = bits & 255;
  m[n - 5] = Math.floor(bits / 2 ** 32) & 255;
  const w = new Uint32Array(64), r = (x, s) => (x >>> s) | (x << (32 - s));
  for (let i = 0; i < n; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = (m[i+4*t] << 24) | (m[i+4*t+1] << 16) | (m[i+4*t+2] << 8) | m[i+4*t+3];
    for (let t = 16; t < 64; t++) {
      const s0 = r(w[t-15], 7) ^ r(w[t-15], 18) ^ (w[t-15] >>> 3);
      const s1 = r(w[t-2], 17) ^ r(w[t-2], 19) ^ (w[t-2] >>> 10);
      w[t] = (w[t-16] + s0 + w[t-7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + w[t]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = new Uint8Array(32);
  H.forEach((v, i) => { out[4*i] = v >>> 24; out[4*i+1] = (v >>> 16) & 255; out[4*i+2] = (v >>> 8) & 255; out[4*i+3] = v & 255; });
  return out;
}
const utf8 = (s) => new TextEncoder().encode(s);
function hmacHex(secreto, mensaje) {
  let k = utf8(secreto);
  if (k.length > 64) k = sha256(k);
  const ki = new Uint8Array(64), ko = new Uint8Array(64);
  for (let i = 0; i < 64; i++) { ki[i] = (k[i] || 0) ^ 0x36; ko[i] = (k[i] || 0) ^ 0x5c; }
  const m = utf8(mensaje), interior = new Uint8Array(64 + m.length);
  interior.set(ki); interior.set(m, 64);
  const ih = sha256(interior), exterior = new Uint8Array(96);
  exterior.set(ko); exterior.set(ih, 64);
  return Array.from(sha256(exterior), (x) => x.toString(16).padStart(2, '0')).join('');
}

const secreto = $env.ENCAJE_SECRET;
if (!secreto) throw new Error('ENCAJE: falta la variable ENCAJE_SECRET en el servicio n8n');
return $input.all().map((item) => {
  const u = String((item.json.query || {}).u || '');
  return { json: { ...item.json, firma: hmacHex(secreto, 'encaje:' + u) } };
});

// n8n · workflow LANOPS-ENCAJE · nodo "Code: entrada"  (detrás de "Code: firma")
// Comprueba el enlace firmado …/webhook/encaje?u=<id>&t=<firma>[&g=0]
const j = $input.first().json;
const q = j.query || {};
const u = String(q.u || '');
const valido = /^\d{1,9}$/.test(u) && typeof q.t === 'string'
  && q.t.length === 64 && q.t.toLowerCase() === String(j.firma || '').toLowerCase();
return [{ json: {
  valido,
  usuario: valido ? Number(u) : null,
  solo_gipuzkoa: q.g !== '0',          // por defecto, solo Gipuzkoa (decisión 31)
}}];

// n8n · workflow LANOPS-ENCAJE · nodo "Code: preparar peticiones"
// Modo: Run Once for All Items · JavaScript
// Entrada: "Postgres: contexto" (1 item) + ítems de "Postgres: prefiltro".
// Salida: un item por vacante NO evaluada, con el cuerpo de la petición a la API de Claude.
// EVALUADORES.prompt = modes/_shared.md + modes/oferta.md + envoltorio.md (en ese orden).
const ctx = $('Postgres: contexto').first().json;
if (!ctx.prompt || !ctx.modelo) throw new Error('ENCAJE: no hay evaluador IA activo con prompt y modelo');
if (!ctx.cv_texto) throw new Error('ENCAJE: el usuario no tiene cv_texto');

const prefs = ctx.preferencias || [];
const lineaPref = (p) => `- ${p.tipo} · ${p.clave} = ${p.valor}${p.tipo === 'peso' && p.peso ? ` (peso ${p.peso})` : ''}`;
const perfil = `<perfil>\n${ctx.cv_texto}\n</perfil>\n\n<preferencias>\n${prefs.map(lineaPref).join('\n') || '(sin preferencias)'}\n</preferencias>`;

const vacantes = $('Postgres: prefiltro').all().map(i => i.json).filter(v => v.vacante && !v.evaluada);
// Sin pendientes: un único item marcador; el IF "¿hay pendientes?" lo manda directo a "Postgres: lista".
if (vacantes.length === 0) return [{ json: { sin_pendientes: true, usuario: ctx.usuario } }];
const fmt = (k, v) => (v === null || v === undefined || v === '' ? `${k}: no consta` : `${k}: ${v}`);

return vacantes.map(v => ({ json: {
  sin_pendientes: false, usuario: ctx.usuario, vacante: v.vacante, evaluador: ctx.evaluador, hash_cv: ctx.hash_cv,
  cuerpo: {
    model: ctx.modelo,
    max_tokens: 4096,
    // Bloque fijo (career-ops + envoltorio): se cachea y se lee al 10 % en las llamadas siguientes.
    system: [{ type: 'text', text: ctx.prompt, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: [
      // Perfil del usuario: igual en todas las vacantes de esta ejecución → segundo punto de caché.
      { type: 'text', text: perfil, cache_control: { type: 'ephemeral' } },
      { type: 'text', text: [
        '<vacante>',
        fmt('Puesto', v.puesto), fmt('Empresa', v.empresa_nombre), fmt('Ubicación', v.ubicacion),
        fmt('Contrato', v.contrato), fmt('Jornada', v.jornada),
        fmt('Salario mínimo anual', v.salario_min ? `${v.salario_min} €` : null),
        'Descripción:', v.requisitos || 'no consta',
        '</vacante>',
      ].join('\n') },
    ]}],
  },
}}));

// n8n · workflow LANOPS-ENCAJE · nodo "Code: leer evaluación"
// Modo: Run Once for All Items · JavaScript
// Entrada: respuestas de "HTTP Request: Claude" (mismo orden que "Code: preparar peticiones").
// Salida: una fila de EVALUACIONES por respuesta válida; las inválidas salen con error y no se insertan.
const ctx = $('Postgres: contexto').first().json;
const pedidas = $('Code: preparar peticiones').all().map(i => i.json);
const alta  = Number(ctx.umbral_alta  ?? 4);
const media = Number(ctx.umbral_media ?? 3);

// Pesos del usuario (PREFERENCIAS tipo 'peso') → peso de cada dimensión.
// Cada dimensión toma el mayor peso de sus claves; sin claves, peso 3 (neutro).
const MAPA = {
  d1_match_cv:     ['euskera', 'idioma'],
  d2_north_star:   ['puesto_objetivo', 'sector', 'situacion_actual'],
  d3_compensacion: ['salario_min'],
  d4_cultura:      ['estabilidad', 'modalidad', 'tamano', 'turnos', 'jornada', 'contrato',
                    'municipio', 'radio_km', 'movilidad', 'fecha_inicio_max'],
  d5_red_flags:    ['ett', 'empresa', 'palabra', 'permiso_trabajo'],
};
const pesos = (ctx.preferencias || []).filter(p => p.tipo === 'peso' && p.peso);
const pesoDim = Object.fromEntries(Object.entries(MAPA).map(([d, claves]) => {
  const ws = pesos.filter(p => claves.includes(p.clave)).map(p => Number(p.peso));
  return [d, ws.length ? Math.max(...ws) : 3];
}));

const DIM = Object.keys(MAPA);
const entero15 = (x) => Number.isInteger(x) && x >= 1 && x <= 5;

return $input.all().map((item, i) => {
  const pedida = pedidas[i];
  const base = { usuario: pedida.usuario, vacante: pedida.vacante, evaluador: pedida.evaluador, hash_cv: pedida.hash_cv };
  try {
    const texto = (item.json.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
    const limpio = texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    const r = JSON.parse(limpio.slice(limpio.indexOf('{'), limpio.lastIndexOf('}') + 1));
    for (const d of DIM) if (!entero15(r[d])) throw new Error(`${d} fuera de 1–5: ${r[d]}`);
    const g = Number(r.global);
    if (!(g >= 1 && g <= 5)) throw new Error(`global fuera de 1–5: ${r.global}`);
    const sumW = DIM.reduce((s, d) => s + pesoDim[d], 0);
    const gp = DIM.reduce((s, d) => s + r[d] * pesoDim[d], 0) / sumW;
    return { json: { ...base, ok: true,
      d1_match_cv: r.d1_match_cv, d2_north_star: r.d2_north_star, d3_compensacion: r.d3_compensacion,
      d4_cultura: r.d4_cultura, d5_red_flags: r.d5_red_flags,
      global: Math.round(g * 10) / 10,
      global_personal: Math.round(gp * 10) / 10,
      banda: g >= alta ? 'Alta' : g >= media ? 'Media' : 'Baja',
      explicacion: String(r.explicacion || '').slice(0, 2000),
      hueco: String(r.hueco || '').slice(0, 1000),
      tokens_cache_leidos: item.json.usage?.cache_read_input_tokens ?? 0,
    }};
  } catch (e) {
    return { json: { ...base, ok: false, error: e.message } };
  }
});

// n8n · workflow LANOPS-ENCAJE · nodo "Code: HTML"
// Modo: Run Once for All Items · JavaScript · Settings del nodo previo "Postgres: lista": Always Output Data ON
// Página accesible (decisión 21): HTML semántico, lang, contraste, sin depender del color.
// [10-oct] Estilo común "Cálido": enlaza https://lanopsdmm.github.io/lanops/styles.css (mismo archivo que la landing de Javi).
// Si Pages no respondiera, la página se sigue leyendo sin estilo. Solo queda en línea la regla funcional de "Cuéntanos por qué".
const filas = $input.all().map(i => i.json).filter(r => r.vacante);
// [07-oct] Botón "Pedir certificado" (decisión 99): reutiliza el enlace firmado del usuario. Solo banda Alta o Media (decisión 100).
const q = $('Webhook /encaje').first().json.query || {};
const pedir = (r) => (r.banda === 'Alta' || r.banda === 'Media')
  ? `<p><a class="boton" href="certificar?u=${encodeURIComponent(q.u)}&amp;t=${encodeURIComponent(q.t)}&amp;v=${r.vacante}">Pedir certificado de esta vacante</a></p>`
  : `<p class="meta">Certificado disponible solo con encaje alto o medio.</p>`;
// [07-oct] Lanbide no publica la empresa (decisión 96).
const empresa = (r) => r.fuente === 'lanbide' ? 'Empresa no publicada · oferta gestionada por Lanbide' : r.empresa;
// [08-oct] Botón "No me interesa" (LANOPS-FEEDBACK, opción B + IA): formulario GET a descartar?u=&t=&a=descartar&v=[&m=][&x=]
// Motivo con "solo quitarla" por defecto (no se aprende nada; mejor aprender menos que aprender mal).
// "x" = el porqué en palabras del usuario (≤ 200): el cuadro aparece al elegir cualquier motivo (se oculta con "solo quitarla";
// CSS :has, sin JavaScript; en navegadores sin :has se ve siempre) y es OBLIGATORIO con "otro motivo" (script mínimo).
// FEEDBACK tampoco acepta "otro" sin texto. Lo lee la IA y no va a ninguna tabla (FEEDBACK no guarda sus ejecuciones correctas).
const MOTIVOS = [['tarea', 'lo que se hace en el puesto'], ['sector', 'el sector'], ['empresa', 'la empresa'],
                 ['salario', 'el salario'], ['lejos', 'está lejos'], ['otro', 'otro motivo']];
const descartar = (r) => `<details class="descartar"><summary>No me interesa</summary>
  <form method="get" action="descartar">
  <input type="hidden" name="u" value="${esc(q.u)}"><input type="hidden" name="t" value="${esc(q.t)}">
  <input type="hidden" name="a" value="descartar"><input type="hidden" name="v" value="${r.vacante}">
  <p><label for="m-${r.vacante}">Motivo:</label>
  <select id="m-${r.vacante}" name="m"><option value="">solo quitarla</option>${MOTIVOS.map(([v, t]) => `<option value="${v}">${t}</option>`).join('')}</select></p>
  <p class="porque"><label for="x-${r.vacante}">Cuéntanos por qué (la IA lo lee para aprender; no se guarda en tu perfil):</label><br>
  <input type="text" id="x-${r.vacante}" name="x" maxlength="200" size="40"></p>
  <p><button type="submit">Descartar</button></p></form></details>`;
// [08-oct] Lista vacía: decir POR QUÉ (antes ponía "Vuelve en unos minutos", y no hay nada evaluando en segundo plano).
// Si el prefiltro no dejó pasar ninguna oferta → no hay ofertas que cumplan; si dejó pasar alguna → la evaluación falló ahora.
const candidatas = $('Postgres: prefiltro').all().filter(i => i.json.vacante).length;
const vacia = candidatas === 0
  ? 'Ahora mismo ninguna oferta abierta cumple tus no negociables y tus exclusiones. Cada mañana entran ofertas nuevas de Lanbide; también puedes revisar lo que LANOPS ha aprendido de ti.'
  : 'No hemos podido evaluar tus ofertas en este momento. Recarga la página dentro de un rato.';
const aprendido = `<p><a href="descartar?u=${encodeURIComponent(q.u)}&amp;t=${encodeURIComponent(q.t)}&amp;a=ver">Lo que LANOPS ha aprendido de ti</a></p>`;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const nota = (g) => Number(g).toFixed(1).replace('.', ',');
const pct = (g) => Math.round(Number(g) * 20);           // decisión 26: % = global × 20
const DIM = [['d1_match_cv', 'Encaje con tu CV'], ['d2_north_star', 'Lo que buscas'],
             ['d3_compensacion', 'Salario'], ['d4_cultura', 'Empresa y condiciones'], ['d5_red_flags', 'Alertas (5 = ninguna)']];

const tarjeta = (r, n) => `
<li class="vac">
  <h2><span class="n">${n}.</span> ${esc(r.puesto)}</h2>
  <p class="meta">${esc(empresa(r))} · ${esc(r.ubicacion || 'ubicación no consta')}</p>
  <div class="barra" aria-hidden="true"><span style="width:${Math.min(100, Math.max(0, pct(r.global)))}%"></span></div>
  <p class="nota"><strong>${pct(r.global)} % · ${nota(r.global)}/5</strong> <span class="banda banda-${({ Alta: 'alto', Media: 'medio', Baja: 'bajo' })[r.banda] || 'bajo'}">encaje ${({ Alta: 'alto', Media: 'medio', Baja: 'bajo' })[r.banda] || esc(r.banda)}</span></p>
  <ul class="dims">${DIM.map(([k, t]) => `<li>${t}: <strong>${r[k]}/5</strong></li>`).join('')}</ul>
  <p>${esc(r.explicacion).replace(/\n/g, '<br>')}</p>
  ${r.hueco ? `<p><strong>Para subir un punto:</strong> ${esc(r.hueco)}</p>` : ''}
  ${r.url_origen ? `<p><a href="${esc(r.url_origen)}" rel="noopener">Ver la oferta original${r.fuente === 'lanbide' ? ' en Lanbide' : ''}</a></p>` : ''}
  ${pedir(r)}
  ${descartar(r)}
</li>`;

const html = `<!doctype html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Tus vacantes · LANOPS</title>
<link rel="stylesheet" href="https://lanopsdmm.github.io/lanops/styles.css">
<style>.descartar:has(option[value=""]:checked) .porque{display:none}</style>
</head><body>
<header><p class="marca">LANOPS</p></header>
<main>
<h1>Tus vacantes con más encaje</h1>
<p>${filas.length ? `${filas.length} vacantes abiertas, ordenadas por lo que tú priorizas.` : vacia}</p>${aprendido}
<ol class="vacs">${filas.map((r, i) => tarjeta(r, i + 1)).join('')}</ol></main>
<footer><p>La IA evalúa; tú decides. Puntuación con la rúbrica abierta de career-ops (MIT). Ofertas de Lanbide: Fuente Lanbide / Open Data Euskadi (CC BY).</p></footer>
<script>
// "Cuéntanos por qué" es obligatorio solo con "otro motivo" (si no hay JavaScript, FEEDBACK lo comprueba igualmente)
document.querySelectorAll('details.descartar select').forEach(function (s) {
  var x = document.getElementById('x-' + s.id.slice(2));
  var f = function () { x.required = s.value === 'otro'; };
  s.addEventListener('change', f); f();
});
</script>
</body></html>`;
return [{ json: { html } }];
